#if (ICU_DEV_ERROR_DETECT==STD_ON)
#include <Det.h>

/*==================[macros]=================================================*/

/*
 * ICU_DET_REPORTERROR()
 *
 * In development mode, this macro reports the indicated error to the
 * Development error tracer (Det). The parameters are:
 *  ApiId     -- API id
 *  ErrorCode -- error code
*/
/* PRQA S 3453 6 *//* Reason for disabling: Implementation often uses macro like function. */
#define ICU_DET_REPORTERROR(ApiId, ErrorCode) \
  (void) Det_ReportError(                     \
                  (uint16)ICU_MODULE_ID,      \
                  (uint8)ICU_INSTANCE_ID_DET, \
                  (uint8)(ApiId),             \
                  (uint8)(ErrorCode))

#else

/*
 * ICU_DET_REPORTERROR()
 *
 * In production mode the macro evaluates to nothing. No error is reported.
*/
#define ICU_DET_REPORTERROR(ApiId, ErrorCode)

#endif
